// Types for the ported renderer (engine/twin3d.js). Only the surface the app calls.
export function start(el: HTMLElement): void;
export function attach(el: HTMLElement): void;
export function detach(el?: HTMLElement | null): void;
export function update(data: unknown): void;
export function resize(): void;
export function setOptical(regions: Record<string, unknown>): void;
export function setFocus(foci: string[]): void;
export function setParked(v: boolean): void;
export const isParked: () => boolean;
export type PinSpec = { region: string; label: string; sub?: string; status: "CRITICAL" | "DYSFUNCTION" | "STRESS" | "NORMAL" };
export function setPins(pins: PinSpec[]): void;
export function setHighlight(region: string | null): void;
export function onPin(cb: ((region: string | null, kind: "hover" | "click") => void) | null): void;
export function onHover(cb: ((region: string | null) => void) | null): void;
export function onPick(cb: ((region: string | null) => void) | null): void;
export function resetView(): void;
export function progress(): { body: boolean; organs: number; total: number; ready: boolean };
export function setHudEnabled(on: boolean): void;
export function focusRegion(region: string | null): void;
